'use strict';
const TUTORIAL_STEPS={
 walk:['1 · เดินซ้ายและขวา','กด ← และ → ลองเดินทั้งสองทิศ แล้วเดินไปหาครูฝึกทางซ้ายล่าง'],
 talk:['2 · คุยกับครูฝึก','เดินไปหาครูฝึกทางซ้ายล่าง แล้วกด Space เพื่อคุย'],
 equipActive:['3 · ติดตั้ง Active','กด S หรือปุ่ม skill → Active → เปลี่ยนสกิลขั้น 1 → เลือกอาวุธที่ถือ → เลือก แล้วปิดหน้าต่าง'],
 useActive:['4 · ลองใช้ Active','กด Q หรือแตะช่อง Q เพื่อใช้สกิลขั้น 1 ที่ติดตั้งไว้ สกิลใช้ MP และมีคูลดาวน์'],
 equipBuff:['5 · ติดตั้ง Buff','กด S → แท็บ Buff → เลือก Buff ช่องแรกของขั้น 1 → เลือกบัฟที่ใช้ได้ แล้วปิดหน้าต่าง'],
 useBuff:['6 · ลองใช้ Buff','กด 1 เพื่อเปิดบัฟ หรือบนมือถือแตะ Buff ด้านบนแล้วเลือกช่อง 1 หลังใช้จะเห็นระยะเวลาบนแถบบัฟ'],
 climb:['7 · ปีนบันได','เดินไปบันไดตรงกลางฝั่งซ้าย กด ↑ ค้างเพื่อขึ้นไปยังแพลตฟอร์มแรก กด ↓ เพื่อปีนลง'],
 jump:['8 · กระโดดข้ามแพลตฟอร์ม','กด → + Space จากขอบแพลตฟอร์ม ข้ามแท่นกลางไปยังทางเดินด้านบนขวา ถ้าตกให้กลับไปปีนบันไดได้'],
 drop:['9 · ลงไปหาวาร์ป','เดินไปปลายทางด้านขวาเหนือวาร์ป กด ↓ ค้าง แล้วกด Space เพื่อทะลุแพลตฟอร์มลงไปชั้นล่าง'],
 portal:['10 · เข้าวาร์ป','ยืนใกล้วาร์ปทางขวาแล้วกด Space เพื่อจบการฝึกและเลือก Emblem 1 ชิ้น'],
 reward:['ฝึกสำเร็จ · เลือก Emblem','เลือก Emblem 1 ชิ้นจาก 12 ประเภท เพื่อใช้ Buff/Passive ข้ามอาวุธ แล้วเข้าสู่หมู่บ้าน']
};
function tutorialModal(...args){modal(...args);$('modal').classList.add('tutorial-modal');$('modal').querySelector('.dialog-card').scrollTop=0}
function tutorialActive(){return !!run?.tutorial&&!player.tutorialCompleted}
function refreshTutorialHint(){const hint=$('tutorialHint');if(!hint)return;hint.hidden=!tutorialActive()||screen!=='play';if(hint.hidden)return;const step=TUTORIAL_STEPS[player.tutorialProgress];$('tutorialStepTitle').textContent=step?.[0]||'';$('tutorialStepText').textContent=step?.[1]||'';$('skillMenuBtn').classList.toggle('tutorial-focus',['equipActive','equipBuff'].includes(player.tutorialProgress))}
function setTutorialStep(step,popup=true){if(!tutorialActive())return;player.tutorialProgress=step;save();refreshTutorialHint();if(popup)showTutorialHelp()}
function showTutorialHelp(){if(!tutorialActive())return;if(player.tutorialProgress==='reward'){showTutorialReward();return}const step=TUTORIAL_STEPS[player.tutorialProgress];const body=document.createElement('div');body.className='tutorial-copy';const note=document.createElement('p');note.textContent=step[1];body.append(note);const mobile=document.createElement('p');mobile.textContent='จอสัมผัส: ลากจอยซ้ายเพื่อเดิน/ปีน แตะปุ่มกระโดดเพื่อกระโดดหรือคุย และลากจอยลงพร้อมแตะกระโดดเพื่อลงชั้นล่าง';body.append(mobile);const actions=[['เริ่มลอง',closeModal,true]];if(['equipActive','equipBuff'].includes(player.tutorialProgress))actions.push(['เปิดหน้าสกิล',()=>{const kind=player.tutorialProgress==='equipBuff'?'buff':'active';closeModal();supportWindowKind=kind;openControlWindow('skill')},true]);tutorialModal(step[0],body,actions);const start=document.createElement('button');start.textContent='เข้าใจแล้ว';start.className='primary';start.onclick=closeModal;$('modalButtons').prepend(start);start.focus()}
function startTutorial(){
 run={id:1,tutorial:true,trial:false,kills:0,time:0,pendingXP:0,eliteKills:0,bossKills:0,finished:false};player.map='tutorial';
 platforms=[{x:0,y:420,w:960,layer:0},{x:0,y:270,w:390},{x:410,y:230,w:80},{x:510,y:190,w:450},{x:820,y:330,w:140}];ladders=[{x:300,top:270,bottom:420}];monsters=[];
 interactables=[{kind:'npc',x:60,y:420,radius:48,action:talkTutorialNPC},{kind:'portal',x:900,y:330,radius:45,action:finishTutorialPortal}];
 const step=player.tutorialProgress||'walk';player.tutorialProgress=step;const at={walk:[900,420],talk:[120,420],equipActive:[120,420],useActive:[120,420],equipBuff:[120,420],useBuff:[120,420],climb:[265,420],jump:[300,270],drop:[760,190],portal:[900,330],reward:[900,330]}[step];player.x=at[0];player.y=at[1];resetMotion();player.invuln=0;player.face=-1;run.tutorialData={left:false,right:false,lastX:player.x,jumps:0,climbed:false,dropped:false};camera=0;$('stageBtn').textContent='ลานฝึก';switchScreen('play');updateUI();save();showTutorialHelp();
}
function talkTutorialNPC(){if(!tutorialActive())return;const step=player.tutorialProgress;if(!['walk','talk','equipActive'].includes(step)){showTutorialHelp();return}if(step==='walk'){showTutorialHelp();return}const pages=[['Active คืออะไร?','Active คือสกิลโจมตีหรือท่าพิเศษ ต้องติดตั้งให้ตรงกับอาวุธหลัก แล้วกด Q / W / E / R ตามขั้น 1–4 ใช้ MP และมี CD บางท่ากดค้างเพื่อชาร์จหรือเปิด–ปิดได้'],['Buff และ Passive','Buff ต้องติดตั้งและกด 1–8 เพื่อเปิดผลชั่วคราว ใช้ MP และมี CD ส่วน Passive แค่ติดตั้งก็ทำงาน ผลของ Buff/Passive ใช้ข้ามอาวุธได้ โดยอาวุธหลักและ Emblem เป็นตัวเปิดสิทธิ์'],['หาสกิลและอัปเกรดจากไหน?','เริ่มด้วยสกิล Lv.1 เปิดกล่องสุ่มสกิลเพื่อรับสกิลซ้ำ แล้วใช้สกิลซ้ำอัปเลเวลผ่านหน้ารายละเอียดสกิลได้ถึง Lv.30 กล่องได้จากมอนสเตอร์/Elite และร้านยาในเมืองมีขายกล่องขั้น 1 จากนั้นลองติดตั้ง Active ขั้น 1 ด้วยตัวเอง']];let page=0;function render(){tutorialModal('ครูฝึก · '+pages[page][0],pages[page][1],[['ถัดไป',()=>{page++;if(page<pages.length)render();else{closeModal();setTutorialStep('equipActive')}},true]])}render()}
function updateTutorial(){if(!tutorialActive()||paused)return;const d=run.tutorialData,step=player.tutorialProgress,dx=player.x-d.lastX;d.lastX=player.x;if(dx<-.1)d.left=true;if(dx>.1)d.right=true;
 if(step==='walk'&&d.left&&d.right)setTutorialStep('talk',false);
 else if(step==='equipActive'&&selectedSkillIds('active').length)setTutorialStep('useActive');
 else if(step==='equipBuff'&&player.weaponLoadout[0].buff[0]&&weaponSkillEnabled(player.weaponLoadout[0].buff[0]))setTutorialStep('useBuff');
 else if(step==='climb'){if(player.climbing)d.climbed=true;if(d.climbed&&player.y<=270.5&&player.ground)setTutorialStep('jump')}
 else if(step==='jump'&&d.jumps>=2&&player.ground&&player.y<=190.5&&player.x>=510)setTutorialStep('drop');
 else if(step==='drop'&&d.dropped&&player.x>=815&&player.y>=329&&player.y<=331&&player.ground)setTutorialStep('portal');
 refreshTutorialHint();
}
function tutorialMark(kind){if(!tutorialActive())return;const d=run.tutorialData,step=player.tutorialProgress;if(kind==='jump'&&step==='jump')d.jumps++;if(kind==='drop'&&step==='drop'&&player.x>=820&&Math.abs(player.y-190)<2)d.dropped=true;if(kind==='active'&&step==='useActive')setTutorialStep('equipBuff');if(kind==='buff'&&step==='useBuff')setTutorialStep('climb')}
function finishTutorialPortal(){if(!tutorialActive())return;if(player.tutorialProgress!=='portal'){showTutorialHelp();return}setTutorialStep('reward')}
function showTutorialReward(){if(!tutorialActive()||player.tutorialProgress!=='reward')return;const body=document.createElement('div');const text=document.createElement('p');text.textContent='เลือก Emblem เริ่มต้น 1 ชิ้น · Common · สวมช่อง Emblem เพื่อใช้ Buff/Passive ของประเภทนั้นร่วมกับอาวุธหลักได้';body.append(text);const grid=document.createElement('div');grid.className='tutorial-emblems';let selected=null;const buttons=[];for(const [weapon,name]of Object.entries(WEAPON_NAMES)){const b=document.createElement('button');b.type='button';b.innerHTML=emblemIcon(weapon);const label=document.createElement('strong');label.textContent=name;b.append(label);b.setAttribute('aria-pressed','false');b.onclick=()=>{selected=weapon;for(const other of buttons)other.setAttribute('aria-pressed',String(other===b));$('claimTutorialEmblem').disabled=false};grid.append(b);buttons.push(b)}body.append(grid);tutorialModal('ฝึกสำเร็จ · เลือก Emblem 1 ชิ้น',body,[['รับ Emblem และเข้าเมือง',()=>claimTutorialEmblem(selected),true]]);const confirm=$('modalButtons').querySelector('button');confirm.id='claimTutorialEmblem';confirm.disabled=true;buttons[0].focus();$('modal').querySelector('.dialog-card').scrollTop=0}
function claimTutorialEmblem(weapon){if(!tutorialActive()||player.tutorialProgress!=='reward'||!WEAPON_NAMES[weapon])return false;if(bagEquipment().length>=EQUIPMENT_CAPACITY){toast('กระเป๋าเต็ม กรุณาจัดพื้นที่ก่อนรับ Emblem');return false}const g={id:crypto.randomUUID(),name:'Emblem '+WEAPON_NAMES[weapon],slot:'emblem',weapon:null,emblemWeapon:weapon,stage:0,level:1,rarity:'common',atk:0,def:0,hp:0,mp:0,bonuses:[]};player.loot.gear.push(g);player.loot.equipped.emblem=g.id;player.tutorialCompleted=true;player.tutorialProgress=null;closeModal();enterTown();save();toast('ได้รับและสวม Emblem '+WEAPON_NAMES[weapon]+' แล้ว · ยินดีต้อนรับสู่หมู่บ้าน');return true}
const tutorialOriginalCast=castWeaponSkill;castWeaponSkill=function(id){const before=player.mp,result=tutorialOriginalCast(id);if(result&&WEAPON_SKILLS[id]?.kind==='active'&&player.mp<before)tutorialMark('active');return result};
const tutorialOriginalBuff=castSupportSkill;castSupportSkill=function(id){const result=tutorialOriginalBuff(id);if(result)tutorialMark('buff');return result};
function drawTrainingTerrain(){for(const p of platforms){if(p.layer===0){cliffPlatform(p,true);grassEdge(p.x,p.y,p.w);continue}const end=p.yEnd??p.y;poly([[p.x,p.y],[p.x+p.w,end],[p.x+p.w,end+15],[p.x,p.y+15]],'#6f6347');for(let x=p.x;x<p.x+p.w;x+=6){const y=platformSurface(p,x);rect(x,y,6,4,'#b2c38a');rect(x,y+5,5,3,'#a38d62')}if(p.yEnd===undefined){rect(p.x,p.y+11,p.w,4,'#514d38');for(let x=p.x+25;x<p.x+p.w;x+=70)rect(x,p.y+15,5,14,'#71664b')}}}
function drawTownBuildings(){for(const shop of [{x:140,y:150,label:'พื้นที่ร้านค้า · ว่าง'},{x:360,y:150,label:'พื้นที่ร้านค้า · ว่าง'},{x:140,y:285,label:'ร้านยา',open:true},{x:360,y:285,label:'พื้นที่ร้านค้า · ว่าง'}]){house(shop.x,shop.y,.48,shop.open?'#b75f51':'#947666');ctx.font='11px Thai,Tahoma';ctx.textAlign='center';rect(shop.x-66,shop.y-110,132,20,'#244c40');ctx.fillStyle='#f1dfaf';ctx.fillText(shop.label,shop.x,shop.y-96)}ctx.font='10px Thai,Tahoma';ctx.textAlign='center';ctx.fillStyle='#305c4d';ctx.fillText('↑ ↓ บันได',500,133);ctx.fillText('วาร์ปเลือกด่าน',900,163)}
function drawTutorialObjects(){const actor={...player,name:'ครูฝึก',x:60,y:420,face:1,invuln:0,vx:0,haste:0,swing:0};drawPlayer(actor);ctx.font='12px Thai,Tahoma';ctx.textAlign='center';rect(12,325,96,23,'#244c40');ctx.fillStyle='#f4dfa5';ctx.fillText('ครูฝึก · Space',60,341);const step=player.tutorialProgress,enabled=['portal','reward'].includes(step);if(enabled)portal(900,330);else{ctx.strokeStyle='#91b5aa';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(900,285,20,40,0,0,Math.PI*2);ctx.stroke()}ctx.font='11px Thai,Tahoma';ctx.fillStyle='#234c3c';ctx.fillText(enabled?'Space · จบการฝึก':'วาร์ป · ทำตามขั้นตอนก่อน',900,227);for(const [x,y,t]of [[300,252,'↑ ปีน'],[445,211,'Space'],[570,171,'Space'],[850,170,'↓ + Space']]){ctx.fillStyle='#294b3c';ctx.fillText(t,x,y)}const target=['walk','talk','equipActive','useActive','equipBuff','useBuff'].includes(step)?[60,350]:step==='climb'?[300,300]:step==='jump'?[445,200]:[900,215];poly([[target[0]-7,target[1]-10],[target[0]+7,target[1]-10],[target[0],target[1]]],'#e7bf65')}
$('tutorialHelpBtn').onclick=showTutorialHelp;
